<script setup lang="ts">import { computed } from 'vue'; import { NAlert, NTag } from 'naive-ui'; import { useChatStore } from '@/stores/hermes/chat'; const chat=useChatStore(); const event=computed(()=>chat.competitionRollbackEvent); const visible=computed(()=>!!event.value && event.value.event !== 'rollback_human')</script>
